package com.eidolon.sc.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Only metadata is retained here. Spoken text uses the existing conversation and pending effects. */
final class CallStore {
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE call_sessions(id TEXT PRIMARY KEY,character TEXT NOT NULL,state TEXT NOT NULL,pending TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL)");}
 static JSONArray all(ChatStore s)throws Exception{JSONArray a=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM call_sessions ORDER BY rowid DESC LIMIT 100",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 static JSONObject get(ChatStore s,String id)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM call_sessions WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static void put(ChatStore s,JSONObject row)throws Exception{ContentValues v=new ContentValues();v.put("id",row.getString("id"));v.put("character",row.getString("character"));v.put("state",row.getString("state"));v.put("pending",row.optString("pending"));v.put("revision",row.optLong("revision"));v.put("body",row.toString());s.getWritableDatabase().insertWithOnConflict("call_sessions",null,v,SQLiteDatabase.CONFLICT_REPLACE);s.getWritableDatabase().execSQL("DELETE FROM call_sessions WHERE id IN (SELECT id FROM call_sessions ORDER BY rowid DESC LIMIT -1 OFFSET 100)");}
 static boolean live(JSONObject r){return r!=null&&!Arrays.asList("ended","missed","rejected","cancelled").contains(r.optString("state"));}
 static JSONObject binding(ChatStore s,String session,long revision)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM call_sessions WHERE pending=? AND revision=? ORDER BY rowid DESC LIMIT 1",new String[]{session,""+revision})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static boolean held(ChatStore s,ChatStore.PendingReply p)throws Exception{return binding(s,p.id,p.revision)!=null;}
 static boolean busy(ChatStore s,String who)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT 1 FROM call_sessions WHERE character=? AND state NOT IN ('ended','missed','rejected','cancelled','ringing') LIMIT 1",new String[]{who})){return c.moveToFirst();}}
 static void recover(ChatStore s)throws Exception{JSONArray a=all(s);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(live(r)&&!r.optString("state").equals("ringing")){String id=r.optString("pending");ChatStore.PendingReply p=s.pending(id);if(p!=null&&p.revision==r.optLong("revision"))s.cancelPending(id);r.put("pending","").put("heard",false).put("state","ended").put("endedAt",System.currentTimeMillis()).put("reason","进程中断，通话已结束，未自动重试请求");put(s,r);}}}
 static void validateBackup(JSONObject d,Set<String> known)throws Exception{JSONArray a=d.getJSONArray("calls");if(a.length()>100)throw new Exception("通话记录过多");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(!known.contains(r.getString("character"))||!ids.add(r.getString("id"))||r.toString().length()>6000||r.optLong("connectedAt")<0||r.optLong("endedAt")<0||r.getString("id").isEmpty()||r.getString("id").length()>100||r.optString("session").length()>100||r.optString("pending").length()>100||r.optLong("turnId")<0||!Arrays.asList("idle","connecting","listening","recognizing","thinking","synthesizing","speaking","committing","muted","paused","failed","ended","ringing","missed","rejected","cancelled").contains(r.getString("state")))throw new Exception("通话记录无效");}}
 static void restore(ChatStore s,JSONObject d,Map<String,String> sessions)throws Exception{s.getWritableDatabase().delete("call_sessions",null,null);if(d.optInt("version")<16)return;JSONArray a=d.getJSONArray("calls");for(int i=a.length()-1;i>=0;i--){JSONObject r=new JSONObject(a.getJSONObject(i).toString());r.put("session",sessions.getOrDefault(r.optString("session"),"")).put("pending","").put("heard",false);if(live(r))r.put("state","ended").put("reason","从备份恢复，不恢复连接或付费请求");put(s,r);}}
 static String context(ChatStore s,String who,java.time.ZoneId zone)throws Exception{JSONArray rows=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM call_sessions WHERE character=? ORDER BY rowid DESC LIMIT 4",new String[]{who})){while(c.moveToNext()&&rows.length()<2){JSONObject r=new JSONObject(c.getString(0));if(r.optLong("connectedAt")<=0)continue;rows.put(new JSONObject().put("connectedAt",MessageTime.label(r.getLong("connectedAt"),zone.getId())).put("endedAt",r.optLong("endedAt")>0?MessageTime.label(r.getLong("endedAt"),zone.getId()):JSONObject.NULL).put("fullyHeardReplies",r.optInt("heardReplies")).put("state",r.getString("state")));}}return rows.length()==0?"":"\n本机实际应用内通话记录（不含运营商电话；未完整播放的回答不算已听见）："+rows;}
 private CallStore(){}
}
